head.b:skin:
/* =============================================================
   Template Name: GAMERDZ1517 Pro Web App Ready
   ============================================================= */
:root {
  --bg-dark: #0b0f19;
  --bg-panel: #0f172a;
  --accent: #38bdf8;
  --rgb-1: #ff0055;
  --rgb-2: #00ffcc;
  --rgb-3: #cc00ff;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
body { margin: 0 !important; padding: 0 !important; overflow-x: hidden !important; background: #0b0f19 !important; font-family: 'Cairo', sans-serif; color: #f8fafc; }

/* 🚀 إخفاء بلوجر بالكامل وعرض تطبيقك كشاشة كاملة عائمة */
#gamerdz-root {
    position: fixed; top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(135deg, rgba(11,15,25,0.65) 0%, rgba(15,23,42,0.55) 100%), url('https://raw.githubusercontent.com/djamekchaouadi/My-api/main/222.jpg') center center / cover no-repeat;
    z-index: 2147483647; overflow-y: auto; font-family: 'Cairo', sans-serif;
    color: #f8fafc; scroll-behavior: smooth; -webkit-overflow-scrolling: touch;
}

#gamerdz-root::-webkit-scrollbar { width: 8px; height: 8px; }
#gamerdz-root::-webkit-scrollbar-track { background: rgba(15, 23, 42, 0.5); }
#gamerdz-root::-webkit-scrollbar-thumb { background: #38bdf8; border-radius: 10px; }
#gamerdz-root::-webkit-scrollbar-thumb:hover { background: #0284c7; }

#app-wrapper { display: flex; flex-direction: column; align-items: center; padding: 20px 15px 40px 15px; box-sizing: border-box; width: 100%; margin: 0 auto; }

.top-bar { width: 100%; max-width: 1200px; display: flex; justify-content: space-between; align-items: center; margin-bottom: 25px; box-sizing: border-box; flex-wrap: wrap; gap: 15px; }

.social-icons { display: flex; gap: 12px; align-items: center; }
.social-icons a { color: #94a3b8; width: 32px; height: 32px; display: flex; justify-content: center; align-items: center; transition: all 0.3s ease; background: rgba(255,255,255,0.05); border-radius: 50%; }
.social-icons a:hover { color: #ffffff; background: #38bdf8; transform: translateY(-3px); box-shadow: 0 5px 15px rgba(56, 189, 248, 0.4); }
.social-icons svg { width: 18px; height: 18px; }

.top-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.action-btn-top { background: rgba(56, 189, 248, 0.15); border: 1px solid rgba(56, 189, 248, 0.3); color: #38bdf8; padding: 6px 15px; border-radius: 8px; font-weight: 700; font-size: 13px; cursor: pointer; transition: all 0.2s ease; font-family: 'Cairo', sans-serif; text-transform: uppercase; backdrop-filter: blur(5px); -webkit-backdrop-filter: blur(5px); }
.action-btn-top:hover { background: #38bdf8; color: #0b0f19; box-shadow: 0 4px 12px rgba(56, 189, 248, 0.3); transform: scale(1.05); }

.engine-v1 { background: rgba(139, 92, 246, 0.15) !important; border-color: rgba(139, 92, 246, 0.5) !important; color: #c4b5fd !important; }
.engine-v2 { background: rgba(16, 185, 129, 0.15) !important; border-color: rgba(16, 185, 129, 0.5) !important; color: #6ee7b7 !important; }

.app-container { width: 100%; max-width: 1200px; background: rgba(15, 23, 42, 0.35); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 20px; padding: 30px; box-shadow: 0 20px 40px rgba(0, 0, 0, 0.6); box-sizing: border-box; }

.header { text-align: center; margin-bottom: 30px; }
.header h1 { font-size: clamp(20px, 4vw, 28px); font-weight: 900; margin: 0; color: #ffffff; direction: ltr; letter-spacing: 1px; text-shadow: 0 2px 10px rgba(0,0,0,0.8); }
.header h3 { font-size: 14px; margin: 10px 0 0 0; color: #38bdf8; font-weight: 700; letter-spacing: 1px; text-shadow: 0 1px 5px rgba(0,0,0,0.8); }

.inputs-container { display: grid; grid-template-columns: 1fr; gap: 20px; margin-bottom: 25px; }
@media (min-width: 850px) { .inputs-container { grid-template-columns: 1fr 1fr; } }

.input-group { display: flex; flex-direction: column; gap: 10px; width: 100%; }
.input-wrapper { position: relative; display: flex; width: 100%; align-items: center; }

input[type="text"] { width: 100%; background: rgba(0, 0, 0, 0.4); border: 1px solid rgba(255, 255, 255, 0.15); border-radius: 10px; color: #f8fafc; padding: 15px 45px 15px 15px; font-size: 14px; font-weight: 700; outline: none; direction: ltr; text-align: left; box-sizing: border-box; transition: all 0.3s; box-shadow: inset 0 2px 5px rgba(0,0,0,0.5); backdrop-filter: blur(5px); }
input[type="text"]:focus { border-color: #38bdf8; background: rgba(0, 0, 0, 0.6); box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.15), inset 0 2px 5px rgba(0,0,0,0.5); }

.copy-btn { position: absolute; right: 8px; top: 50%; transform: translateY(-50%); background: rgba(255,255,255,0.05); border: 1px solid rgba(255,255,255,0.1); color: #cbd5e1; cursor: pointer; padding: 8px; border-radius: 8px; transition: all 0.2s; display: flex; align-items: center; justify-content: center; }
.copy-btn:hover { color: #ffffff; background: #38bdf8; border-color: #38bdf8; }
.copy-btn svg { width: 15px; height: 15px; }

button.btn-main { border: none; border-radius: 12px; color: white; cursor: pointer; padding: 15px 10px; font-family: inherit; display: flex; flex-direction: column; justify-content: center; align-items: center; text-align: center; transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1); height: 100%; box-shadow: 0 4px 15px rgba(0,0,0,0.4); }
.btn-title { font-size: 14px; font-weight: 900; letter-spacing: 0.5px; }
.btn-desc { font-size: 11px; font-weight: 600; opacity: 0.85; margin-top: 5px; }
button.btn-main:active { transform: scale(0.96); }

.btn-blue { background: linear-gradient(135deg, rgba(37,99,235,0.9), rgba(59,130,246,0.9)); border: 1px solid rgba(59, 130, 246, 0.4); }
.btn-cyan { background: linear-gradient(135deg, rgba(13,148,136,0.9), rgba(20,184,166,0.9)); border: 1px solid rgba(20, 184, 166, 0.4); }
.btn-red { background: linear-gradient(135deg, rgba(220,38,38,0.9), rgba(239,68,68,0.9)); border: 1px solid rgba(239, 68, 68, 0.4); }
.btn-green { background: linear-gradient(135deg, rgba(22,163,74,0.9), rgba(34,197,94,0.9)); border: 1px solid rgba(34, 197, 94, 0.4); }
.btn-dark { background: linear-gradient(135deg, rgba(51,65,85,0.9), rgba(71,85,105,0.9)); border: 1px solid rgba(255, 255, 255, 0.1); }
.btn-purple { background: linear-gradient(135deg, rgba(124,58,237,0.9), rgba(139,92,246,0.9)); border: 1px solid rgba(139, 92, 246, 0.4); }
.btn-orange { background: linear-gradient(135deg, rgba(234,88,12,0.9), rgba(249,115,22,0.9)); border: 1px solid rgba(249, 115, 22, 0.4); }
.btn-gold { background: linear-gradient(135deg, rgba(202,138,4,0.9), rgba(234,179,8,0.9)); border: 1px solid rgba(234, 179, 8, 0.4); }
.btn-disabled { background: rgba(30,41,59,0.7) !important; color: #64748b !important; cursor: not-allowed !important; border: 1px solid rgba(255,255,255,0.05); box-shadow: none; }

button.btn-main:not(.btn-disabled):hover { filter: brightness(1.1); box-shadow: 0 8px 20px rgba(0,0,0,0.6); transform: translateY(-2px); }

.action-buttons { display: grid; grid-template-columns: 1fr; gap: 15px; margin-bottom: 30px; }
@media (min-width: 500px) { .action-buttons { grid-template-columns: 1fr 1fr; } }
@media (min-width: 1000px) { .action-buttons { grid-template-columns: repeat(4, 1fr); } }

.selection-boxes { display: grid; grid-template-columns: 1fr; gap: 20px; margin-bottom: 30px; direction: rtl; }
@media (min-width: 850px) { .selection-boxes { grid-template-columns: repeat(3, 1fr); } }

.content-box { background: rgba(0, 0, 0, 0.4); border: 1px solid rgba(255, 255, 255, 0.05); border-radius: 16px; padding: 20px; display: flex; flex-direction: column; gap: 10px; max-height: 400px; overflow-y: auto; box-shadow: inset 0 0 20px rgba(0,0,0,0.5); backdrop-filter: blur(5px); }
.content-box h4 { margin: 0 0 15px 0; color: #38bdf8; font-size: 15px; font-weight: 800; text-align: center; padding-bottom: 12px; border-bottom: 1px solid rgba(255,255,255,0.05); position: sticky; top: -20px; background: rgba(0,0,0,0.8); z-index: 2; padding-top: 20px; backdrop-filter: blur(5px); }

.checkbox-label { font-size: 13px; font-weight: 600; display: flex; align-items: center; gap: 12px; cursor: pointer; color: #e2e8f0; padding: 8px 12px; border-radius: 8px; transition: all 0.2s; background: rgba(255,255,255,0.02); border: 1px solid transparent; }
.checkbox-label:hover { background: rgba(56, 189, 248, 0.1); border-color: rgba(56, 189, 248, 0.3); color: #fff; transform: translateX(-3px); }
.checkbox-label input { accent-color: #38bdf8; width: 18px; height: 18px; cursor: pointer; }

.log-wrapper { background: rgba(2, 6, 23, 0.5); backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 16px; height: 280px; display: flex; flex-direction: column; direction: ltr; overflow: hidden; box-shadow: inset 0 0 30px rgba(0,0,0,0.5); }
.log-header { background: rgba(15, 23, 42, 0.7); padding: 12px 20px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.1); }
.log-header-left { display: flex; align-items: center; gap: 15px; }
.mac-dots { display: flex; gap: 6px; } .mac-dots span { width: 12px; height: 12px; border-radius: 50%; box-shadow: inset 0 1px 3px rgba(0,0,0,0.5); }
.mac-dots .red { background: #ef4444; } .mac-dots .yellow { background: #f59e0b; } .mac-dots .green { background: #10b981; }
.log-header-text { font-size: 12px; color: #94a3b8; font-weight: 800; letter-spacing: 1.5px; font-family: 'Consolas', monospace; text-shadow: 0 1px 3px rgba(0,0,0,0.8); }

.download-btn { background: rgba(16, 185, 129, 0.15); border: 1px solid rgba(16, 185, 129, 0.4); color: #10b981; border-radius: 8px; padding: 6px 15px; font-size: 12px; font-weight: 700; cursor: pointer; display: flex; align-items: center; gap: 8px; transition: all 0.2s; }
.download-btn:hover { background: #10b981; color: #020617; box-shadow: 0 0 15px rgba(16, 185, 129, 0.4); }
.download-btn svg { width: 14px; height: 14px; fill: currentColor; }

.log-content { flex: 1; padding: 15px 20px; overflow-y: auto; font-family: 'Consolas', monospace; font-size: 13px; line-height: 1.8; font-weight: 600; white-space: pre-wrap; text-shadow: 0 1px 3px rgba(0,0,0,0.8); }
.log-item { padding: 5px 0; border-bottom: 1px dashed rgba(255,255,255,0.1); }
.success-text { color: #10b981; } .error-text { color: #ef4444; } .info-text { color: #38bdf8; } .warn-text { color: #f59e0b; }

/* نوافذ المودال */
.modal-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(2, 6, 23, 0.95); backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); z-index: 9999999; display: none; align-items: center; justify-content: center; padding: 20px; box-sizing: border-box; }
.modal-overlay.show { display: flex; }
.modal-content { background: #0f172a; border-radius: 20px; padding: 30px 20px; width: 100%; text-align: center; box-shadow: 0 25px 50px rgba(0,0,0,0.8); max-height: 90vh; overflow-y: auto; display: flex; flex-direction: column; position: relative;}

.ad-modal { max-width: 450px; border: 1px solid rgba(139, 92, 246, 0.5); }
.ad-modal h2 { color: #ffffff; font-size: 22px; margin: 0 0 10px 0; font-weight: 900; text-shadow: 0 2px 5px rgba(0,0,0,0.5); } 
.ad-modal p { color: #cbd5e1; font-size: 14px; margin: 0 0 25px 0; font-weight: 600; }
#ad-space { margin: 0 auto 25px auto; width: 100%; min-height: 250px; background: #000; border-radius: 12px; display: flex; align-items: center; justify-content: center; overflow: hidden; border: 1px solid rgba(255,255,255,0.05); }
#btnUnlock { background: #1e293b; border: 1px solid #334155; border-radius: 12px; color: #94a3b8; padding: 16px 20px; font-family: 'Cairo', sans-serif; font-weight: 800; font-size: 15px; width: 100%; cursor: not-allowed; transition: all 0.3s; margin-top: auto; }
#btnUnlock.active { background: linear-gradient(135deg, #6d28d9, #8b5cf6); border-color: transparent; color: #ffffff; cursor: pointer; box-shadow: 0 10px 25px rgba(139, 92, 246, 0.4); }

.warning-modal { max-width: 550px; border: 2px solid #ef4444; box-shadow: 0 10px 40px rgba(239, 68, 68, 0.2); }
.warning-modal h2 { color: #ef4444; font-size: 24px; margin: 0 0 15px 0; font-weight: 900; }
.warning-modal p { color: #e2e8f0; font-size: 15px; line-height: 1.8; margin: 0 0 25px 0; font-weight: 600; text-align: right; }
#btnAcceptWarning { background: linear-gradient(135deg, #16a34a, #22c55e); border: none; border-radius: 12px; color: #fff; padding: 15px 20px; font-family: 'Cairo', sans-serif; font-weight: 800; font-size: 15px; width: 100%; cursor: pointer; transition: all 0.3s; }

/* الشاشة الترحيبية الاحترافية */
.welcome-screen-overlay {
    position: fixed; top: 0; left: 0; right: 0; bottom: 0;
    background: linear-gradient(135deg, rgba(11,15,25,0.60) 0%, rgba(2,132,199,0.20) 100%), url('https://raw.githubusercontent.com/djamekchaouadi/My-api/main/222.jpg') center center / cover no-repeat;
    backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px); z-index: 999999999; display: flex; justify-content: center; align-items: center;
}
.welcome-screen-overlay:not(.show) { display: none; }

.welcome-screen-content {
    background: rgba(15, 23, 42, 0.35); backdrop-filter: blur(12px); -webkit-backdrop-filter: blur(12px); border: 1px solid rgba(56, 189, 248, 0.3); border-radius: 24px; padding: 40px 30px; width: 90%; max-width: 500px; text-align: center; box-shadow: 0 25px 50px rgba(0,0,0,0.8), inset 0 0 20px rgba(56, 189, 248, 0.1); position: relative; overflow: hidden;
}

.welcome-btn { background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255, 255, 255, 0.1); border-radius: 12px; color: #f8fafc; padding: 16px 20px; font-family: 'Cairo', sans-serif; font-size: 15px; font-weight: 800; cursor: pointer; display: flex; align-items: center; gap: 15px; transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1); width: 100%; text-align: right; position: relative; }
.welcome-btn svg { width: 22px; height: 22px; flex-shrink: 0; transition: transform 0.3s ease; }
.welcome-btn:hover { color: #fff; }

.wb-1 { border-right: 4px solid #38bdf8; } .wb-1 svg { fill: #38bdf8; } .wb-1:hover { background: linear-gradient(135deg, rgba(2, 132, 199, 0.9), rgba(56, 189, 248, 0.9)); border-color: transparent; box-shadow: 0 10px 25px rgba(56, 189, 248, 0.4); transform: translateY(-3px); }
.wb-2 { border-right: 4px solid #a855f7; } .wb-2 svg { fill: #a855f7; } .wb-2:hover { background: linear-gradient(135deg, rgba(147, 51, 234, 0.9), rgba(192, 132, 252, 0.9)); border-color: transparent; box-shadow: 0 10px 25px rgba(168, 85, 247, 0.4); transform: translateY(-3px); }
.wb-3 { border-right: 4px solid #f97316; } .wb-3 svg { fill: #f97316; } .wb-3:hover { background: linear-gradient(135deg, rgba(234, 88, 12, 0.9), rgba(251, 146, 60, 0.9)); border-color: transparent; box-shadow: 0 10px 25px rgba(249, 115, 22, 0.4); transform: translateY(-3px); }
.wb-4 { border-right: 4px solid #10b981; } .wb-4 svg { fill: #10b981; } .wb-4:hover { background: linear-gradient(135deg, rgba(5, 150, 105, 0.9), rgba(52, 211, 153, 0.9)); border-color: transparent; box-shadow: 0 10px 25px rgba(16, 185, 129, 0.4); transform: translateY(-3px); }

/* مودال المشغل السينمائي الشامل */
.preview-modal-fullscreen { position: fixed; top: 0; left: 0; right: 0; bottom: 0; width: 100%; height: 100%; background: #0b0f19; z-index: 9999999; display: none; flex-direction: column; overflow: hidden; }
.preview-modal-fullscreen.show { display: flex; }

.preview-header-bar { display: flex; align-items: center; justify-content: space-between; padding: 15px 25px; background: #0f172a; border-bottom: 1px solid rgba(56, 189, 248, 0.3); z-index: 100; flex-shrink: 0; }
.btn-back { background: rgba(239, 68, 68, 0.1); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.4); padding: 8px 20px; border-radius: 8px; cursor: pointer; font-family: 'Cairo', sans-serif; font-weight: 800; font-size: 14px; display: flex; align-items: center; gap: 10px; transition: all 0.3s; }
.btn-back:hover { background: #ef4444; color: #fff; box-shadow: 0 4px 15px rgba(239, 68, 68, 0.4); transform: translateX(3px); }
.preview-brand { color: #38bdf8; font-weight: 900; font-size: 18px; letter-spacing: 1px; }

.player-and-tabs-area { flex-shrink: 0; width: 100%; display: flex; flex-direction: column; align-items: center; background: #0b0f19; padding: 15px 20px 10px 20px; box-sizing: border-box; border-bottom: 1px solid rgba(255,255,255,0.05); z-index: 90; box-shadow: 0 10px 20px rgba(0,0,0,0.5); }
.player-wrapper { width: 100%; max-width: 1000px; position: relative; background: #000; border: 1px solid rgba(56, 189, 248, 0.4); border-radius: 12px; overflow: hidden; box-shadow: 0 10px 30px rgba(0,0,0,0.8), 0 0 20px rgba(56, 189, 248, 0.15); margin-bottom: 15px; display: flex; align-items: center; justify-content: center; }

#myVideoPlayer { width: 100%; aspect-ratio: 16 / 9; max-height: 60vh; background: #000; outline: none; object-fit: contain; }
.video-header-overlay { position: absolute; top: 0; left: 0; right: 0; padding: 15px 20px; background: linear-gradient(to bottom, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0) 100%); display: flex; justify-content: space-between; align-items: flex-start; z-index: 5; pointer-events: none; }
.video-title { color: #f8fafc; font-size: 16px; font-weight: 900; text-shadow: 0 2px 5px #000; text-align: right; direction: rtl; max-width: 75%; line-height: 1.4; }
.hevc-warning { font-size: 12px; color: #ef4444; font-weight: 800; background: rgba(0,0,0,0.7); padding: 4px 8px; border-radius: 6px; display: none; }

.tabs-header { display: flex; justify-content: center; gap: 10px; width: 100%; max-width: 1000px; background: rgba(15, 23, 42, 0.8); border-radius: 12px; padding: 5px; border: 1px solid rgba(255,255,255,0.05); }
.tab-btn { flex: 1; background: transparent; border: none; color: #94a3b8; font-size: 15px; font-weight: 800; cursor: pointer; padding: 12px 20px; border-radius: 8px; transition: all 0.3s ease; font-family: 'Cairo', sans-serif; display: flex; align-items: center; justify-content: center; gap: 8px; }
.tab-btn:hover { color: #fff; background: rgba(255,255,255,0.05); }
.tab-btn.active { background: #38bdf8; color: #0f172a; box-shadow: 0 4px 15px rgba(56, 189, 248, 0.3); }

.lists-scroll-area { flex: 1; width: 100%; overflow-y: auto; padding: 15px 20px 40px 20px; box-sizing: border-box; background: #0b0f19; }
.tab-content { display: none; animation: fadeIn 0.4s ease; width: 100%; max-width: 1000px; margin: 0 auto; }
.tab-content.active { display: block; }
@keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

.items-list-container { display: flex; flex-direction: column; gap: 8px; }
.item-list-row { background: rgba(15, 23, 42, 0.6); border: 1px solid rgba(255,255,255,0.05); border-radius: 12px; padding: 12px 15px; display: flex; align-items: center; cursor: pointer; transition: all 0.2s ease; direction: rtl; backdrop-filter: blur(5px); justify-content: flex-start;}
.item-list-row:hover { border-color: #38bdf8; background: rgba(56, 189, 248, 0.1); box-shadow: 0 4px 15px rgba(56, 189, 248, 0.15); transform: translateX(-3px); }

.play-icon-box { width: 32px; height: 32px; background: rgba(56, 189, 248, 0.15); border-radius: 50%; display: flex; justify-content: center; align-items: center; flex-shrink: 0; transition: all 0.3s; }
.item-list-row:hover .play-icon-box { background: #38bdf8; transform: scale(1.1); box-shadow: 0 0 10px rgba(56,189,248,0.5); }
.play-icon-box svg { width: 12px; height: 12px; fill: #38bdf8; transition: fill 0.3s; margin-left: -2px; }
.item-list-row:hover .play-icon-box svg { fill: #0f172a; }

.item-list-row span { font-size: 15px; font-weight: 700; color: #e2e8f0; text-align: right; flex: 1; line-height: 1.4; transition: color 0.3s; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-right: 15px;}
.item-list-row:hover span { color: #fff; }

body.script:
//
let currentEngine = 'V1';
const ENGINES = {
    V1: { url: "https://gamer-dz.onrender.com", name: "PLAN A" },
    V2: { url: "https://gamerdz1517.onrender.com", name: "PLAN B" } 
};

const DB_URL = "https://raw.githubusercontent.com/djamekchaouadi/SERVER/main/1.txt";
const ADSTERRA_DIRECT_LINK = "https://forbesresistread.com/g1e0hxpa2?key=7d7011dbeba839707ae96752413ee4d8";

let loadServerClickCount = 0;
let scanClickCount = 0;

const AudioContext = window.AudioContext || window.webkitAudioContext;
let audioCtx;

function playSound(type) {
    try {
        if (!audioCtx) audioCtx = new AudioContext();
        if (audioCtx.state === 'suspended') audioCtx.resume();

        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.connect(gain);
        gain.connect(audioCtx.destination);

        const now = audioCtx.currentTime;

        if (type === 'welcome') {
            osc.type = 'sine';
            osc.frequency.setValueAtTime(523.25, now); 
            osc.frequency.setValueAtTime(659.25, now + 0.1); 
            osc.frequency.setValueAtTime(783.99, now + 0.2); 
            osc.frequency.setValueAtTime(1046.50, now + 0.3); 
            gain.gain.setValueAtTime(0.1, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.8);
            osc.start(now);
            osc.stop(now + 0.8);
        } else if (type === 'click') {
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, now);
            gain.gain.setValueAtTime(0.05, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.1);
            osc.start(now);
            osc.stop(now + 0.1);
        } else if (type === 'success') {
            osc.type = 'triangle';
            osc.frequency.setValueAtTime(880, now); 
            osc.frequency.setValueAtTime(1108.73, now + 0.15); 
            gain.gain.setValueAtTime(0.08, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.5);
            osc.start(now);
            osc.stop(now + 0.5);
        } else if (type === 'error') {
            osc.type = 'sawtooth';
            osc.frequency.setValueAtTime(200, now);
            osc.frequency.linearRampToValueAtTime(100, now + 0.3);
            gain.gain.setValueAtTime(0.08, now);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.3);
            osc.start(now);
            osc.stop(now + 0.3);
        }
    } catch (e) { console.log('Audio not supported'); }
}

