let currentLang = 'ar';
let currentActionType = ''; 

function applyTranslations() {
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        if(dict[currentLang][key]) {
            if(el.tagName === 'INPUT' && el.type === 'text') el.placeholder = dict[currentLang][key];
            else el.innerHTML = dict[currentLang][key];
        }
    });
}

function toggleLanguage() {
    playSound('click');
    currentLang = currentLang === 'ar' ? 'fr' : 'ar';
    document.documentElement.dir = currentLang === 'ar' ? 'rtl' : 'ltr';
    applyTranslations();
    addLog(currentLang === 'ar' ? "تم تغيير اللغة إلى العربية." : "Langue changée en Français.", "info");
}

document.getElementById('btnLang').addEventListener('click', toggleLanguage);
document.getElementById('btnWelcomeLang').addEventListener('click', toggleLanguage);

document.getElementById('btnEngine').addEventListener('click', () => {
    let btn = document.getElementById('btnEngine');
    if (currentEngine === 'V1') {
        currentEngine = 'V2';
        btn.className = "action-btn-top engine-v2";
        btn.innerHTML = `⚙️ السيرفر: ${ENGINES.V2.name}`;
    } else {
        currentEngine = 'V1';
        btn.className = "action-btn-top engine-v1";
        btn.innerHTML = `⚙️ السيرفر: ${ENGINES.V1.name}`;
    }
    addLog(`[*] تم التبديل إلى: ${ENGINES[currentEngine].name}`, "info");
});

function addLog(message, type = 'normal') {
    const div = document.createElement('div'); div.className = 'log-item';
    if(type === 'success') div.classList.add('success-text'); else if(type === 'error') div.classList.add('error-text'); else if(type === 'warn') div.classList.add('warn-text'); else if(type === 'info') div.classList.add('info-text');
    div.innerHTML = `> ${message}`; document.getElementById('logList').appendChild(div); document.getElementById('logList').scrollTop = document.getElementById('logList').scrollHeight;
}

let loadedAccounts = []; let successfulServers = []; let scannedCategories = { live: [], vod: [], series: [] }; let pendingCredentials = {};

window.copyToClipboard = function(elementId, btnElement) {
    const textToCopy = document.getElementById(elementId).value;
    if (!textToCopy) return; navigator.clipboard.writeText(textToCopy).then(() => {
        const originalIcon = btnElement.innerHTML;
        btnElement.innerHTML = `<svg viewBox="0 0 448 512" fill="currentColor"><path d="M438.6 105.4c12.5 12.5 12.5 32.8 0 45.3l-256 256c-12.5 12.5-32.8 12.5-45.3 0l-128-128c-12.5-12.5-12.5-32.8 0-45.3s32.8-12.5 45.3 0L160 338.7 393.4 105.4c12.5-12.5 32.8-12.5 45.3 0z"/></svg>`;
        btnElement.style.color = "#10b981"; setTimeout(() => { btnElement.innerHTML = originalIcon; btnElement.style.color = "#cbd5e1"; }, 1500);
    });
}

document.getElementById('btnClear').addEventListener('click', () => {
    document.getElementById('warning-modal').classList.add('show');
});

document.getElementById('btnAcceptWarning').addEventListener('click', async () => {
    document.getElementById('warning-modal').classList.remove('show');

    addLog(dict[currentLang].msgDbConnecting, "info"); loadedAccounts = [];
    try {
        const response = await fetch(`${DB_URL}?t=${Date.now()}`);
        if (!response.ok) throw new Error("Network Error");
        const lines = (await response.text()).split(/\r?\n/);
        let panel = "";
        for (let line of lines) { 
            line = line.trim(); 
            if (line.startsWith("PANEL")) panel = line.replace("PANEL", "").trim(); 
            else if (line.startsWith("MAC")) { 
                let mac = line.replace("MAC", "").trim(); 
                if (panel && mac) loadedAccounts.push({ panel, mac }); 
            } 
        }
        if(loadedAccounts.length > 0) { 
            playSound('welcome'); 
            document.getElementById('txtM3U').value = dict[currentLang].msgDbFound.replace('{count}', loadedAccounts.length); 
            addLog(dict[currentLang].msgDbSuccess.replace('{count}', loadedAccounts.length), "success"); 
        } else throw new Error();
    } catch (error) { 
        playSound('error'); 
        addLog(dict[currentLang].msgDbError, "error"); 
    }
});

document.getElementById('btnNext').addEventListener('click', () => {
    playSound('click'); 
    if (loadedAccounts.length === 0) { addLog(dict[currentLang].msgLoadError, "error"); return; }

    loadServerClickCount++;
    if (loadServerClickCount % 3 === 0) { window.open(ADSTERRA_DIRECT_LINK, '_blank'); }

    const item = loadedAccounts.shift();
    document.getElementById('txtStation').value = item.panel; document.getElementById('txtTime').value = item.mac;
    document.getElementById('txtM3U').value = dict[currentLang].msgLoadRemain.replace('{count}', loadedAccounts.length);
    addLog(`${dict[currentLang].msgLoadSuccess} <br/><span style="color:#e2e8f0;" dir="ltr">${item.panel}</span>`, "info");
    disableActionButtons();
});

document.getElementById('btnReplay').addEventListener('click', () => {
    playSound('click'); 
    document.getElementById('txtStation').value = ''; document.getElementById('txtTime').value = ''; document.getElementById('txtM3U').value = '';
    addLog(dict[currentLang].logCleared, "info");
    disableActionButtons();
});

function disableActionButtons() {
    document.getElementById('selectionContainer').style.display = 'none'; 
    document.getElementById('btnConvertXtream').disabled = true; document.getElementById('btnConvertXtream').classList.add('btn-disabled');
    document.getElementById('btnDownloadM3u').disabled = true; document.getElementById('btnDownloadM3u').classList.add('btn-disabled');
    document.getElementById('btnPreviewContent').disabled = true; document.getElementById('btnPreviewContent').classList.add('btn-disabled');
}

document.getElementById('btnScanServer').addEventListener('click', async () => {
    let server = document.getElementById('txtStation').value.trim(); const mac = document.getElementById('txtTime').value.trim();
    if(!server.startsWith("http") || !mac) { playSound('error'); addLog(dict[currentLang].msgUrlInvalid, "error"); return; }
    server = server.replace(/\/c\/?$/i, '').replace(/\/$/i, '');

    scanClickCount++;
    if (scanClickCount % 5 === 0) { window.open(ADSTERRA_DIRECT_LINK, '_blank'); }

    addLog(dict[currentLang].msgScanConnecting, "info");
    try {
        let scanUrl = `${getApiBase()}/api/scan?server=${encodeURIComponent(server)}&mac=${encodeURIComponent(mac)}`;
        const res = await fetch(scanUrl);
        const data = await res.json();
        if(data.error || !data.success) throw new Error(data.error || dict[currentLang].msgScanFailed);

        scannedCategories = data.categories; 
        renderCategoryBoxes();
        document.getElementById('selectionContainer').style.display = 'grid';

        let btnConv = document.getElementById('btnConvertXtream'); btnConv.disabled = false; btnConv.classList.remove('btn-disabled'); btnConv.classList.add('btn-purple');
        let btnM3u = document.getElementById('btnDownloadM3u'); btnM3u.disabled = false; btnM3u.classList.remove('btn-disabled'); btnM3u.classList.add('btn-orange');
        let btnPrev = document.getElementById('btnPreviewContent'); btnPrev.disabled = false; btnPrev.classList.remove('btn-disabled'); btnPrev.classList.add('btn-gold');

        successfulServers.push(`PORTAL: ${server}\nMAC: ${mac}`);
        playSound('success'); 
        addLog(currentLang === 'ar' ? "[نجاح] تم الفحص! حدد الجروبات المطلوبة." : "[Succès] Scan terminé !", "success");
    } catch(e) { playSound('error'); addLog(dict[currentLang].msgScanFailed, "error"); }
});

function renderCategoryBoxes() {
    const renderList = (items, containerId, type) => {
        const container = document.getElementById(containerId);
        container.innerHTML = ''; 
        items.forEach(cat => { container.innerHTML += `<label class="checkbox-label"><input type="checkbox" name="cat_${type}" value="${cat.id}"/> ${cat.title}</label>`; });
    };
    renderList(scannedCategories.live, 'liveCategoriesList', 'live'); 
    renderList(scannedCategories.vod, 'vodCategoriesList', 'vod'); 
    renderList(scannedCategories.series, 'seriesCategoriesList', 'series');
}

async function getSelectedData() {
    let server = document.getElementById('txtStation').value.trim().replace(/\/c\/?$/i, '').replace(/\/$/i, '');
    let mac = document.getElementById('txtTime').value.trim();

    let liveCb = document.querySelectorAll('input[name="cat_live"]');
    let selectedLive = Array.from(liveCb).filter(cb => cb.checked).map(cb => cb.value);

    let vodCb = document.querySelectorAll('input[name="cat_vod"]');
    let selectedVod = Array.from(vodCb).filter(cb => cb.checked).map(cb => cb.value);

    let seriesCb = document.querySelectorAll('input[name="cat_series"]');
    let selectedSeries = Array.from(seriesCb).filter(cb => cb.checked).map(cb => cb.value);

    let totalAvailable = liveCb.length + vodCb.length + seriesCb.length;
    let totalSelected = selectedLive.length + selectedVod.length + selectedSeries.length;

    if(totalSelected === 0) { addLog(dict[currentLang].errNoSelection, "warn"); return null; }
    if(totalAvailable > 0 && totalSelected === totalAvailable) { addLog(dict[currentLang].errAllSelected, "error"); return null; }

    return { server, mac, l: selectedLive, v: selectedVod, s: selectedSeries };
}

async function generateAccountData() {
    let sd = await getSelectedData();
    if(!sd) return false;

    addLog(dict[currentLang].msgGenWait, "info");
    try {
        const res = await fetch(`${getApiBase()}/create_account`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ mac: sd.mac, server: sd.server, selections: { l: sd.l, v: sd.v, s: sd.s } })
        });
        const data = await res.json();
        if (data.success) {
            pendingCredentials = { mac: sd.mac, xtreamPassword: data.password, server: sd.server, selections: { l: sd.l, v: sd.v, s: sd.s } };
            return true;
        } else { addLog(data.error, "error"); return false; }
    } catch (e) { addLog(dict[currentLang].errGen, "error"); return false; }
}

let adInterval;
function startAdModal() {
    document.getElementById('ad-modal').classList.add('show');
    document.getElementById('btnUnlock').disabled = true; 
    document.getElementById('btnUnlock').classList.remove('active');
    let seconds = 12; 
    document.getElementById('txtBtnUnlock').innerHTML = dict[currentLang].modalWait.replace('{s}', seconds);

    clearInterval(adInterval);
    adInterval = setInterval(() => {
        seconds--; 
        document.getElementById('txtBtnUnlock').innerHTML = dict[currentLang].modalWait.replace('{s}', seconds);
        if(seconds <= 0) {
            clearInterval(adInterval); 
            document.getElementById('btnUnlock').disabled = false; 
            document.getElementById('btnUnlock').classList.add('active');
            playSound('success'); 
            if (currentActionType === 'm3u') document.getElementById('txtBtnUnlock').innerHTML = dict[currentLang].m3uModalUnlock;
            else document.getElementById('txtBtnUnlock').innerHTML = dict[currentLang].modalUnlock;
        }
    }, 1000);
}

document.getElementById('btnConvertXtream').addEventListener('click', async () => {
    playSound('click');
    currentActionType = 'xtream'; let success = await generateAccountData(); if(success) startAdModal();
});

document.getElementById('btnDownloadM3u').addEventListener('click', async () => {
    playSound('click');
    currentActionType = 'm3u'; let success = await generateAccountData(); if(success) startAdModal();
});

document.getElementById('btnUnlock').addEventListener('click', () => {
    playSound('click');
    if (currentActionType === 'xtream') {
        window.open(ADSTERRA_DIRECT_LINK, '_blank'); 
        document.getElementById('ad-modal').classList.remove('show');
        addLog("====== XTREAM CREDENTIALS ======", "info");
        addLog(`USERNAME: ${pendingCredentials.mac}`, "success");
        addLog(`PASSWORD: ${pendingCredentials.xtreamPassword}`, "success");
        addLog(`URL: ${getApiBase().replace("https://", "http://")}`, "success");
        addLog(dict[currentLang].msgReady, "warn");
    } else if (currentActionType === 'm3u') {
        let rawData = JSON.stringify({ mac: pendingCredentials.mac, server: pendingCredentials.server, selections: pendingCredentials.selections });
        let encodedData = encodeSafeBase64(rawData);
        const downloadUrl = `${getApiBase()}/get.php?username=${pendingCredentials.mac}&password=${pendingCredentials.xtreamPassword}&type=m3u_plus&data=${encodedData}`;
        window.open(downloadUrl, '_blank'); 
        addLog(dict[currentLang].msgM3uDownloading, "success");
        document.getElementById('ad-modal').classList.remove('show');
    }
});

