    document.getElementById('liveItemsList').innerHTML = '<span style="color:#f59e0b; padding:15px; text-align:center; display:block;">جاري التحميل...</span>';
    document.getElementById('vodItemsList').innerHTML = '<span style="color:#f59e0b; padding:15px; text-align:center; display:block;">جاري التحميل...</span>';

    const playIconSvg = `<div class="play-icon-box"><svg viewBox="0 0 384 512"><path d="M73 39c-14.8-9.1-33.4-9.4-48.5-.9S0 62.6 0 80V432c0 17.4 9.4 33.4 24.5 41.9s33.7 8.1 48.5-.9L361 297c14.3-8.7 23-24.2 23-41s-8.7-32.2-23-41L73 39z"/></svg></div>`;

    if(sd.l.length > 0) {
        fetch(`${getApiBase()}/api/get_items`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ server: sd.server, mac: sd.mac, type: "itv", selectedCats: sd.l }) })
        .then(r => r.json()).then(res => {
            if(res.success && res.data.length > 0) {
                let html = '';
                res.data.forEach(item => {
                    let safeName = escapeHtml(item.name);
                    let jsSafeName = safeName.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
                    html += `<div class="item-list-row" onclick="playVideo('${sd.server}', '${sd.mac}', '${item.id}', 'itv', '${jsSafeName}')">${playIconSvg}<span>${safeName}</span></div>`;
                });
                document.getElementById('liveItemsList').innerHTML = html;
            } else document.getElementById('liveItemsList').innerHTML = '<span style="padding:15px; color:#ef4444; text-align:center; display:block;">لا يوجد محتوى.</span>';
        });
    }

    if(sd.v.length > 0) {
        fetch(`${getApiBase()}/api/get_items`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ server: sd.server, mac: sd.mac, type: "vod", selectedCats: sd.v }) })
        .then(r => r.json()).then(res => {
            if(res.success && res.data.length > 0) {
                let html = '';
                res.data.forEach(item => {
                    let safeName = escapeHtml(item.name);
                    let jsSafeName = safeName.replace(/\\/g, "\\\\").replace(/'/g, "\\'");
                    html += `<div class="item-list-row" onclick="playVideo('${sd.server}', '${sd.mac}', '${item.id}', 'vod', '${jsSafeName}')">${playIconSvg}<span>${safeName}</span></div>`;
                });
                document.getElementById('vodItemsList').innerHTML = html;
            } else document.getElementById('vodItemsList').innerHTML = '<span style="padding:15px; color:#ef4444; text-align:center; display:block;">لا يوجد محتوى.</span>';
        });
    }
});

let mpegtsPlayer = null;
let hlsPlayer = null;

window.playVideo = function(server, mac, streamId, type, name) {
    playSound('click');
    document.getElementById('videoTitle').innerText = name;
    let proxyUrl = `${getApiBase()}/proxy_stream?server=${encodeURIComponent(server)}&mac=${encodeURIComponent(mac)}&stream_id=${streamId}&type=${type}`;
    let video = document.getElementById('myVideoPlayer');
    let hevcWarning = document.getElementById('hevcWarning');

    if (name.toUpperCase().includes('HEVC')) { hevcWarning.style.display = 'block'; } else { hevcWarning.style.display = 'none'; }
    cleanupPlayers();

    if (mpegts.getFeatureList().mseLivePlayback) {
        mpegtsPlayer = mpegts.createPlayer({ type: type === 'vod' ? 'mp4' : 'm2ts', isLive: type === 'itv', url: proxyUrl });
        mpegtsPlayer.attachMediaElement(video);
        mpegtsPlayer.load();
        mpegtsPlayer.play().catch(e => { fallbackToHLS(proxyUrl, video); });
    } else {
        fallbackToHLS(proxyUrl, video);
    }
};

function fallbackToHLS(url, video) {
    if (Hls.isSupported()) {
        hlsPlayer = new Hls();
        hlsPlayer.loadSource(url);
        hlsPlayer.attachMedia(video);
        hlsPlayer.on(Hls.Events.MANIFEST_PARSED, function() { video.play(); });
    } else {
        video.src = url;
        video.play();
    }
}

function cleanupPlayers() {
    let video = document.getElementById('myVideoPlayer');
    if (mpegtsPlayer) { mpegtsPlayer.pause(); mpegtsPlayer.unload(); mpegtsPlayer.detachMediaElement(); mpegtsPlayer.destroy(); mpegtsPlayer = null; }
    if (hlsPlayer) { hlsPlayer.destroy(); hlsPlayer = null; }
    video.pause(); video.removeAttribute('src'); video.load();
}

document.getElementById('btnClosePreview').addEventListener('click', () => {
    playSound('click');
    document.getElementById('preview-modal').classList.remove('show');
    cleanupPlayers();
});

applyTranslations();
